    val rtcache_wr_cuid = Output(UInt(log2Ceil(CONFIG.GPU.NUM_CU).W))
    val rtcache_wr_data = Output(new datatype_rtcache(NUM_RESOURCE, NUM_RT_RESULT = NUM_RT_RESULT))
  })

